function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function Shot([string]$path){$window.UpdateLayout();$a=$window.PointToScreen([Windows.Point]::new(0,0));$b=$window.PointToScreen([Windows.Point]::new($window.ActualWidth,$window.ActualHeight));$w=[Math]::Max(1,[int]($b.X-$a.X));$h=[Math]::Max(1,[int]($b.Y-$a.Y));$bitmap=[Drawing.Bitmap]::new($w,$h);$g=[Drawing.Graphics]::FromImage($bitmap);try{$g.CopyFromScreen([int]$a.X,[int]$a.Y,0,0,[Drawing.Size]::new($w,$h));$bitmap.Save($path)}finally{$g.Dispose();$bitmap.Dispose()};"${w}x${h}"}
function MultiXld(){[HalconDotNet.HObject]$all=$null;[HalconDotNet.HOperatorSet]::GenEmptyObj([ref]$all);foreach($length in @(35,50,85,150,220)){[HalconDotNet.HObject]$one=$null;[HalconDotNet.HOperatorSet]::GenContourPolygonXld([ref]$one,[HalconDotNet.HTuple]@([double]80,80),[HalconDotNet.HTuple]@([double]80,([double]80+$length)));[HalconDotNet.HObject]$combined=$null;try{[HalconDotNet.HOperatorSet]::ConcatObj($all,$one,[ref]$combined);$all.Dispose();$all=$combined;$combined=$null}finally{$one.Dispose();if($null-ne$combined){$combined.Dispose()}}};$all}
