$store=$main.GetField('batchTraceStore',$private).GetValue($window);foreach($i in 0..5){$record=[Activator]::CreateInstance($recordType);$record.BatchId=('BATCH-20260812-{0:000}'-f($i+1));$record.RecipeName=if($i-lt4){'Bearing Inspection'}else{'Cap Inspection'};$record.RecipeFingerprint=('a'*(60))+('{0:0000}'-f$i);$record.StartedAtUtc=[DateTime]::UtcNow.AddMinutes(-($i*18)).ToString('O');$record.CompletedAtUtc=[DateTime]::UtcNow.AddMinutes(-($i*18)+1).ToString('O');$record.Scope=if($i%3-eq0){'All'}elseif($i%3-eq1){'Selected'}else{'Current'};$record.TotalCount=4;$record.TotalElapsedMilliseconds=1234+$i*157;$record.Outcome=if($i-eq2){'NG'}elseif($i-eq4){'Error'}else{'OK'};$items=[Activator]::CreateInstance($listType);foreach($j in 0..3){$item=[Activator]::CreateInstance($itemType);$item.Sequence=$j;$item.FileName=('part_{0:00}.png'-f($j+1));$item.FilePath=Join-Path $temp $item.FileName;$item.State=if($j-eq3-and$record.Outcome-ne'OK'){$record.Outcome}else{'OK'};$item.ResultCode=$item.State;$item.ElapsedMilliseconds=240+$j*17;$item.Message=if($item.State-eq'OK'){'完整流程通过'}else{'尺寸判定未通过'};$items.Add($item)};$record.Items=$items;$store.Save($record)|Out-Null}
$main.GetMethod('ReloadBatchTraceHistory',$private).Invoke($window,[object[]]@($false))|Out-Null
$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.Left=2;$window.Top=2;$window.Width=1900;$window.Height=1060;$window.Topmost=$true;$window.Show();(F 'BottomPanelRow').Height=[Windows.GridLength]::new(390);(F 'BottomTabs').SelectedItem=(F 'BatchTraceTab');Pump 700;$traceSize=Shot $TraceOutputPath
$flow=$main.GetField('flowTools',$private).GetValue($window);$main.GetMethod('DisposeFlowTools',$private).Invoke($window,@())|Out-Null;$flow.Clear();$create=$main.GetMethod('CreateFlowTool',$private);$producer=$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,'SubpixelEdgeExtraction'),'Source XLD',$true,$null));$class=$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,'XldLengthClassification'),'Length Classification',$true,$null));$class.Parameters.XldLengthShortMaximum=50;$class.Parameters.XldLengthMediumMaximum=150;$class.SetInputBinding('XLD',$producer.ToolId,'XLD');$flow.Add($producer);$flow.Add($class);$xld=MultiXld;try{$snapshotType=$assembly.GetType('HalconWinFormsDemo.Models.VmXldSnapshot',$true);$snap=$snapshotType.GetMethod('Create',[Reflection.BindingFlags]'Static,Public').Invoke($null,[object[]]@($xld,$producer.ToolId,$producer.InstanceName,'XLD'));$producer.SetOutputValue('XLD',$snap);$producer.ResultCode='OK'}finally{$xld.Dispose()};$main.GetMethod('ExecuteFlowTool',$private).Invoke($window,[object[]]@($class,'S44 UI'))|Out-Null;(F 'FlowToolList').SelectedItem=$class;$main.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($class))|Out-Null;(F 'RightTabs').SelectedItem=(F 'DockConfigurationTab');(F 'DockConfigurationTabs').SelectedIndex=0;(F 'BottomPanelRow').Height=[Windows.GridLength]::new(140);$main.GetMethod('RefreshResultOverlayLayers',$private).Invoke($window,@())|Out-Null;$main.GetMethod('ScheduleRefreshDisplay',$private).Invoke($window,@())|Out-Null;Pump 700;$classSize=Shot $ClassOutputPath
